-- WBR-491 Part 2: Import inventoried free David Bee books into Solution Vault Book Shelf.
-- Additive migration on branch wbr-491-latemorning-20261125; safe and idempotent.
-- Books with PDFs in Downloads/Drive without dedicated Hub covers yet are seeded as
-- published web books using /assets/eee/vault.png so they render cleanly immediately
-- without broken private storage paths, and idk-wtf-im-doing receives its cover.

-- Attach the existing legacy cover asset for idk-wtf-im-doing where no cover is set yet.
update public.solution_vault_books
set cover_url = '/assets/vault/idk-wtf-im-doing-cover.jpg', updated_at = now()
where slug = 'idk-wtf-im-doing' and (cover_url is null or cover_url = '');

insert into public.solution_vault_books (slug, title, subtitle, description, format, status, cover_url, sort_order, chapters)
values
  (
    $wb_book$what-to-post$wb_book$,
    $wb_book$What to Post When You Don't Have Experience or Time$wb_book$,
    $wb_book$The 30-Day Content Strategy Digital Book$wb_book$,
    $wb_book$A 5-stage system for creators and new entrepreneurs to choose a 30-day focus, clean up profiles, pick core formats, set a weekly flow, and build real engagement.$wb_book$,
    'web',
    'published',
    '/assets/eee/vault.png',
    60,
    $wb_book$[{"id":"intro","title":"Introduction: The 30-Day Plan","content":"T HE 30-DAY PLAN FOR NEW ENTREPRENEURS\nWhat to\nPost\nWhen You\nDon't Have\nExperience or Time\nFor the creator who scrolls other people's content all day, knows they should be posting, and has been \"about to start\" for months.\nSTAGE 1 · IDENTIFY THE PLAN STAGE 2 · SET THE STAGE\nSTAGE 3 · CONTENT TYPES STAGE 4 · BUILD YOUR FLOW\nSTAGE 5 · ENGAGE TO GROW\n\nI NTRODUCTION\nWelcome to the most important 30 days of your creative life.\nBecause this? This isn't another \"content calendar.\" This isn't some one-size-fits-all blueprint made for influencers with teams of editors. And this definitely isn't about posting just to post.\nThis is about you showing the f*ck up, loudly, consistently, with purpose. For yourself. For your audience. For what you're building next.\n\"You don't need more motivation. You don't need another book to highlight and forget. You need to do the thing.\"\nOver the next few pages, you're going to build a system that actually makes sense, not just content ideas, but content identity. Not just trends, but traction. Not just goals, but momentum you can feel.\nYou need to post when it's not perfect. You need to commit to being consistent, even if nobody claps yet. Because that's how the game changes. That's how brands are born.\n\"I'm doing this. All of it. No half-assing. No disappearing. I'm building something real and I'm starting now.\""},{"id":"stage-1","title":"Stage 1: Identify The Plan","content":"S TAGE ONE\nIdentify The Plan\nYou're not building an empire in a week. You're building momentum.\n01 Pick ONE Primary Goal for the Next 30-180\nDays\nChoose the path that matches where you're at right now.\n🚀\n📥\n💰\nGrow\nFollowers\nStarting from scratch or rebuilding. Build your voice, confidence, and audience.\nEverything else follows.\nCollect Emails\nYou have a freebie or offer coming soon. Your backup plan if you're kinda-sorta ready for business.\nSell a Product\nYour business is already running with an offer, funnel, and follow- up in place. Only then.\nBuilds launch list\nPairs with value content\nNeeds basic setup\nPossible to start hot\nNot for beginners\nRequires full funnel\nFastest to start\nNo tech setup\nBuilds organic proof\n⚠ REAL TALK\nIf you don't know what to sell yet, or you're still refining your message, pick \"Grow\nFollowers.\" You'll get clarity faster. You'll build proof while you learn. Everything else becomes easier later.\n02 Make a Mini Goal You Can See\nRealistic, visible, motivating, not a revenue projection.\n\n\"By the end of 30 days, I want to...\"\n✓ Post every day, even if it's not perfect\n✓ Gain 100 new followers across all platforms\n✓ Start getting comments and replies on my videos\n✓ Send 25 people to my freebie / group / offer\n✓ Prove to myself I can actually do this\nYou don't have to go viral. You just have to post.\n03 Commit to the Routine, Not the Results\nThis month is about building the muscle, not hitting the numbers.\n\"If I only had one job for the next 30 days, it would be to...\"\nExample: \"Post 1 video per day and reply to 5 comments.\"\n\"And if I do that, I trust that...\"\nExample: \"...my content will get better and people will start noticing.\""},{"id":"stage-2","title":"Stage 2: Set the Stage","content":"S TAGE TWO\nSet the Stage\nLook like you mean it, because strangers will check.\n01 Match Your Setup to Your Goal\n🚀\n📥\n💰\nGrowing\nFollowers\nCollecting\nEmails\nSelling\nSomething\n✓ Clean, bold, recognizable profile pic\n✓ Consistent name across platforms\n✓ 1-line bio: who → what they get → why follow\n✓ Everything above, plus...\n✓ Everything above, plus...\n✓ Landing page with opt-in (Carrd)\n✓ Email tool connected\n✓ Simple sales page or booking link\n✓ Checkout process tested\n✓ Simple CTA in bio\n✓ Simple welcome email ready\n✓ Test the form yourself\n✓ Testimonials in featured content\n✓ Pin a featured intro post or video\n02 Profile Clean-Up Checklist\n✓ Profile pic is recent, high contrast, not chaotic\n✓ Name + handle match across all platforms\n✓ Bio has ONE clear CTA (freebie, group, etc.)\n\n✓ Link in bio is live and points to your main action\n✓ Featured/pinned content is intentional and fresh\n✓ Banner updated with your main theme or brand phrase\n✓ Welcome post added if you have a group or YouTube\n⚠ REAL TALK\n\"You don't need to look like a brand. But you need to look like a real person who didn't just make this account last night.\"\n03 Write Your Bio + CTA\nBio Formula:\nI help [who] do/escape/understand [what], so they can [outcome].\nFollow me for [topic or vibe], new stuff daily.\nExample: \"I help burned-out employees escape retail and launch online. Follow for tips, rants, and no-\nBS business strategy.\"\nYour CTA options:\n→ \"Get the free checklist\"\n→ \"Join my free challenge\"\n→ \"Watch the video that started it all\"\n→ \"See how I make content in under 1 hour/day\""},{"id":"stage-3","title":"Stage 3: Pick Your Content Types","content":"S TAGE THREE\nPick Your\nContent Types\nPost what fits your energy, your brand, and your current level of sanity.\n01 Why Variety Matters\nYou don't need to do everything, but if every video feels the same, people scroll past. Variety keeps your audience curious, keeps you interested, and different platforms reward different formats.\nYour goal isn't to go viral. It's to get noticed enough to matter.\n02 The Content Menu\nMark what feels like you, not what sounds cool. What you'll actually do without quitting.\n\n🎙️\n💡\n📹\n📋\n🌀\n🤖\n03 Talking Head, Teach, rant, explain, story-tell\n🎭\nSkits / Chaos Shorts, High-energy absurdist takes\nTips & Tutorials, Quick wins they can try today\nTrend-Based, Viral audios or formats\n🎬\nDuets & Replies, React to comments, stitch takes\n👣\nDay-in-the-Life, Show your work, your vibe\n\"Skip If You're Not Me\", Public accountability\n🧠\nHot Takes, Bold opinions that stir engagement\nThemed Series, 30-day challenges, daily truths\n📚\nProof / Screenshots, Show results without bragging\nFaceless AI Videos, Reddit/Quora voiceovers\n😅\nReaction Content, Memes, bad advice breakdowns\n💡 REPURPOSE LIKE A PRO\nCut old YouTube/podcasts into short clips. Repost a banger from 6 months ago. Record the same topic 3 ways, serious, silly, soft, to see what hits. Add new captions, crop differently, change the hook. Easy refresh.\nChoose Your Core 2 + Wildcard\nMy two core formats this month:\nMy wildcard format to experiment with:\nYou can change these later, but only after you actually try them. Do each format at least 3-5 times before deciding it's \"not for you.\"\n\n04 Choose Your Output Level\n🟢\n🟢\n🔵\nTrial Mode\n1 post / week\nBasic\nMode\n3 posts / week\nGrowth\nMode\n5 posts / week\n\"I'm going to post ___ videos per week for the next 30 days.\"\nScreenshot this. Set a reminder. Tell a friend. This is where it starts to get real.\n🔴\nBeast\nMode\nDaily or 2x/day"},{"id":"stage-4","title":"Stage 4: Build a Weekly Flow","content":"S TAGE FOUR\nBuild a\nWeekly Flow\nYou don't need a content calendar. You need a rhythm that works.\n01 Your Realistic Daily Workflow\nExpect it to take longer than it should. That's normal. It gets faster.\n⚠ REAL TALK\nIf you think filming a 60-second video will take 5 minutes, you're gonna get big mad and quit.\nIt will feel messy. You'll want to restart 10 times. Editing will make you want to throw your phone. That's normal. You only improve by posting bad stuff consistently.\n45 min Film 1-2 Videos\nOne quick raw shoot-and-post. One with more intention, scripted or thought-through.\n30-120 min Edit, Caption, Upload captions.\nUse CapCut or built-in platform tools. Post to 3-4 platforms with batched\n60 min Reply to Comments + DMs\nPrioritize real convos. If someone asks something good, turn it into your next post.\n60 min Scroll With Purpose your niche.\nLeave meaningful comments. Stitch or duet viral takes. Debate something real in\n\n02 Your Weekly Theme Flow\nMonday\nPLAN\nTuesday\nSCRIPT\n→ Pick 3-5 topics\n→ Save trending audios\n→ Choose your \"proof\" moment\n→ Outline 1-2 Talking Head videos\n→ Bullet a skit or trend idea\n→ Draft captions if batching\nWednesday\nFILM + POST\nThursday\nCOMMENT WAR\n→ Record in one block\n→ Post 1 fun + 1 authority piece\n→ Save drafts if needed\n→ Debate someone respectfully\n→ Stitch or duet viral takes\n→ Drop opinions in others' comments\nFriday\nSTORYTIME OR PROOF\nSaturday\nCHILL + COMMUNITY\n→ Share a result or lesson\n→ Talk about a transformation\n→ Share a real screenshot or DM\n→ Reply to comments\n→ Share a \"lazy\" day post\n→ Ask your audience a question\nSunday\nRECAP + BTS\n→ Reflect on the week\n→ Show behind-the-scenes\n→ Film your to-do list video\nWrite your own custom weekly rhythm:\nMon\nTue\nWed\nThu\nFri\nSat\n\nSun\n\"Done is better than perfect.\nPosted is better than planned.\""},{"id":"stage-5","title":"Stage 5: Engage to Grow","content":"S TAGE FIVE\nEngage to Grow\nPosting is step one. Growth happens when you stop yelling and start listening.\n01 Forget the Metrics That Don't Matter\nNo one cares how many likes you got if no one knows your name.\nDon't track follower count, view averages, or conversion rates yet. Your only metric:\nDid people respond to your stuff?\nIf yes\n→ Reply\nIf no\n→ Go start a conversation\n02 Weekly Engagement Habits\nYou don't need a spreadsheet. You need a routine of interaction.\n✓ Reply to every single comment, yes, even the dumb ones. Use voice replies for speed + human connection. Don't let haters get the last word.\n✓ Follow creators with similar content, their audience is your audience. Lurk their comments and stitch the best takes.\n✓ Comment on 3-5 videos every day, admire them? Say why. Disagree? Say it better. Start debates, ask better questions, drop one-liners.\n\n✓ Duet or Stitch 1 hot take per week, add your spin or correction. Do it fast. Hot takes get shared.\n✓ Join conversations in groups or threads, find niche Facebook groups, YouTube comment wars, Reddit threads. Drop answers better than the original creator.\n✓ Share content from another creator, screenshot, duet, or tag them. Shows you're plugged in, starts relationships.\n✓ DM 1 person per week you admire, \"Been loving your stuff lately, how's it going?\" Might lead to a collab. Might lead nowhere. Both are fine.\n03 Your Weekly Engagement Checklist\nEven if you don't post, do these every week:\n✓ Replied to all comments\n✓ Left 5+ new comments on others' content\n✓ Followed 2 new creators in my niche\n✓ Stitched or dueted 1 video\n✓ Shared someone else's content\n✓ DMed 1 person I admire\n\"You're not 'posting content.'\nYou're building a voice inside an ecosystem.\""},{"id":"closing","title":"What Comes Next: Build With Bee","content":"Congrats. You just showed up.\nThat says something about you. You didn't skim. You didn't scroll past. You actually sat down and built a full 5-stage content strategy, one that's simple, honest, and built for real people with real lives.\n🎯\n✨\nA clear outcome that actually matters to you\nAn online setup that won't embarrass you when people click\n🎭\n📅\nContent formats that fit your personality, not some algorithm god\nA weekly flow that respects your time and still gets results\n💬\nA game plan for engagement that goes beyond \"post and pray\"\nAnd now comes the most dangerous part of any journey: trying to do it all alone. You get hyped. You map it all out. You do a few posts. And then life hits. You get behind. You miss a day. Then another. And the dream you swore you were going to make happen? It fades into another folder of \"someday.\"\nI don't want that for you. Not after how far you've come.\n\nBuild With Bee\nThis is my private program for creators, coaches, and solopreneurs. It's not a course. It's not a passive membership. It's a collaboration. You bring the goals. I bring the experience. Together, we build the system you'll actually stick with, daily support, strategic feedback, and a custom plan that grows with you.\nColoradoMastermind.com/#BuildWithBee"}]$wb_book$::jsonb
  ),
